1	package httpclient
2	
3	import (
4		"context"
5		"crypto/tls"
6		"fmt"
7		"net"
8		"net/http"
9		"net/url"
10		"strings"
11		"sync"
12		"time"
13	
14		"github.com/imroc/req/v3"
15	)
16	
17	type ImpersonationMode string
18	
19	const (
20		ImpersonationNative ImpersonationMode = "native"
21		ImpersonationFixed  ImpersonationMode = "fixed"
22		ImpersonationAuto   ImpersonationMode = "auto"
23	)
24	
25	type Browser string
26	
27	const (
28		BrowserChrome  Browser = "chrome"
29		BrowserFirefox Browser = "firefox"
30		BrowserSafari  Browser = "safari"
31	)
32	
33	type Options struct {
34		Client        ClientOptions
35		Transport     TransportOptions
36		Impersonation ImpersonationOptions
37	}
38	
39	type ClientOptions struct {
40		Jar           http.CookieJar
41		CheckRedirect func(req *http.Request, via []*http.Request) error
42		Timeout       time.Duration
43	}
44	
45	type TransportOptions struct {
46		Proxy               func(*http.Request) (*url.URL, error)
47		DialContext         func(ctx context.Context, network, address string) (net.Conn, error)
48		TLSClientConfig     *tls.Config
49		TLSHandshakeTimeout time.Duration
50	}
51	
52	type ImpersonationOptions struct {
53		Mode    ImpersonationMode
54		Browser Browser
55		Session *ImpersonationSession
56	}
57	
58	type ImpersonationSession struct {
59		mu         sync.RWMutex
60		selections map[string]impersonationSelection
61	}
62	
63	type impersonationSelection struct {
64		browser          Browser
65		fallbackDisabled bool
66	}
67	
68	func NewImpersonationSession() *ImpersonationSession {
69		return &ImpersonationSession{
70			selections: make(map[string]impersonationSelection),
71		}
72	}
73	
74	func (s *ImpersonationSession) load(url string) (impersonationSelection, bool) {
75		s.mu.RLock()
76		defer s.mu.RUnlock()
77		selection, ok := s.selections[url]
78		return selection, ok
79	}
80	
81	func (s *ImpersonationSession) store(url string, browser Browser) {
82		s.mu.Lock()
83		defer s.mu.Unlock()
84		s.selections[url] = impersonationSelection{browser: browser}
85	}
86	
87	func (s *ImpersonationSession) disableFallback(url string) {
88		s.mu.Lock()
89		defer s.mu.Unlock()
90		s.selections[url] = impersonationSelection{fallbackDisabled: true}
91	}
92	
93	func (s *ImpersonationSession) Clear() {
94		s.mu.Lock()
95		defer s.mu.Unlock()
96		clear(s.selections)
97	}
98	
99	func NewClient(options Options) (*http.Client, error) {
100		var transport http.RoundTripper
101		switch options.Impersonation.Mode {
102		case "", ImpersonationNative:
103			transport = newNativeTransport(options.Transport)
104		case ImpersonationFixed:
105			browserTransport, err := newBrowserTransport(options.Transport, options.Impersonation.Browser)
106			if err != nil {
107				return nil, err
108			}
109			transport = browserTransport
110		case ImpersonationAuto:
111			browserTransports := make(map[Browser]http.RoundTripper, 3)
112			for _, browser := range []Browser{BrowserChrome, BrowserFirefox, BrowserSafari} {
113				browserTransport, err := newBrowserTransport(options.Transport, browser)
114				if err != nil {
115					return nil, err
116				}
117				browserTransports[browser] = browserTransport
118			}
119			transport = &adaptiveTransport{
120				native:   newNativeTransport(options.Transport),
121				browsers: browserTransports,
122				jar:      options.Client.Jar,
123				session:  options.Impersonation.Session,
124			}
125		default:
126			return nil, fmt.Errorf("unsupported impersonation mode %q", options.Impersonation.Mode)
127		}
128	
129		return &http.Client{
130			Transport:     transport,
131			Jar:           options.Client.Jar,
132			CheckRedirect: options.Client.CheckRedirect,
133			Timeout:       options.Client.Timeout,
134		}, nil
135	}
136	
137	func newNativeTransport(options TransportOptions) *http.Transport {
138		var tlsConfig *tls.Config
139		if options.TLSClientConfig != nil {
140			tlsConfig = options.TLSClientConfig.Clone()
141		}
142		return &http.Transport{
143			Proxy:               options.Proxy,
144			DialContext:         options.DialContext,
145			TLSClientConfig:     tlsConfig,
146			TLSHandshakeTimeout: options.TLSHandshakeTimeout,
147			ForceAttemptHTTP2:   true,
148		}
149	}
150	
151	func newBrowserTransport(options TransportOptions, browser Browser) (http.RoundTripper, error) {
152		client := req.NewClient()
153		client.SetProxy(options.Proxy)
154		if options.DialContext != nil {
155			client.SetDial(options.DialContext)
156		}
157		client.SetTLSHandshakeTimeout(options.TLSHandshakeTimeout)
158		if options.TLSClientConfig != nil {
159			tlsConfig := options.TLSClientConfig.Clone()
160			if len(tlsConfig.NextProtos) == 0 {
161				tlsConfig.NextProtos = []string{"h2", "http/1.1"}
162			}
163			client.SetTLSClientConfig(tlsConfig)
164		}
165	
166		switch browser {
167		case BrowserChrome:
168			client.ImpersonateChrome()
169		case BrowserFirefox:
170			client.ImpersonateFirefox()
171		case BrowserSafari:
172			client.ImpersonateSafari()
173		default:
174			return nil, fmt.Errorf("unsupported browser %q", browser)
175		}
176	
177		return &defaultHeaderTransport{
178			next:     client.GetClient().Transport,
179			defaults: client.Headers.Clone(),
180		}, nil
181	}
182	
183	type defaultHeaderTransport struct {
184		next     http.RoundTripper
185		defaults http.Header
186	}
187	
188	func (t *defaultHeaderTransport) RoundTrip(request *http.Request) (*http.Response, error) {
189		request = request.Clone(request.Context())
190		request.Header = request.Header.Clone()
191		for key, values := range t.defaults {
192			if len(request.Header.Values(key)) == 0 {
193				request.Header[key] = append([]string(nil), values...)
194			}
195		}
196		return t.next.RoundTrip(request)
197	}
198	
199	func (t *defaultHeaderTransport) CloseIdleConnections() {
200		closeIdleConnections(t.next)
201	}
202	
203	type adaptiveTransport struct {
204		native   http.RoundTripper
205		browsers map[Browser]http.RoundTripper
206		jar      http.CookieJar
207		session  *ImpersonationSession
208	}
209	
210	func (t *adaptiveTransport) RoundTrip(request *http.Request) (*http.Response, error) {
211		cacheKey := requestCacheKey(request.URL)
212		if t.session != nil {
213			if selected, ok := t.session.load(cacheKey); ok {
214				if selected.fallbackDisabled {
215					return t.native.RoundTrip(request)
216				}
217				return t.browsers[selected.browser].RoundTrip(request)
218			}
219		}
220	
221		response, err := t.native.RoundTrip(request)
222		if !shouldFallback(response, err) {
223			return response, err
224		}
225	
226		retry, ok := cloneRequestForRetry(request)
227		if !ok {
228			return response, err
229		}
230		if response != nil {
231			applyResponseCookies(t.jar, request, retry, response)
232			_ = response.Body.Close()
233		}
234	
235		browser := browserFromUserAgent(request.UserAgent())
236		response, err = t.browsers[browser].RoundTrip(retry)
237		if t.session != nil {
238			if isSuccessfulFallback(response, err) {
239				t.session.store(cacheKey, browser)
240			} else if err == nil && response != nil {
241				t.session.disableFallback(cacheKey)
242			}
243		}
244		return response, err
245	}
246	
247	func requestCacheKey(requestURL *url.URL) string {
248		cacheURL := *requestURL
249		cacheURL.Fragment = ""
250		cacheURL.RawFragment = ""
251		return cacheURL.String()
252	}
253	
254	func applyResponseCookies(jar http.CookieJar, request, retry *http.Request, response *http.Response) {
255		if jar == nil {
256			return
257		}
258		jar.SetCookies(request.URL, response.Cookies())
259		jarCookies := jar.Cookies(request.URL)
260		jarCookieNames := make(map[string]struct{}, len(jarCookies))
261		for _, cookie := range jarCookies {
262			jarCookieNames[cookie.Name] = struct{}{}
263		}
264		existingCookies := retry.Cookies()
265		retry.Header.Del("Cookie")
266		for _, cookie := range existingCookies {
267			if _, replaced := jarCookieNames[cookie.Name]; !replaced {
268				retry.AddCookie(cookie)
269			}
270		}
271		for _, cookie := range jarCookies {
272			retry.AddCookie(cookie)
273		}
274	}
275	
276	func (t *adaptiveTransport) CloseIdleConnections() {
277		closeIdleConnections(t.native)
278		for _, transport := range t.browsers {
279			closeIdleConnections(transport)
280		}
281	}
282	
283	func closeIdleConnections(transport http.RoundTripper) {
284		if closer, ok := transport.(interface{ CloseIdleConnections() }); ok {
285			closer.CloseIdleConnections()
286		}
287	}
288	
289	func shouldFallback(response *http.Response, err error) bool {
290		if err != nil {
291			return true
292		}
293		if response == nil {
294			return false
295		}
296		return response.StatusCode == http.StatusForbidden ||
297			strings.EqualFold(response.Header.Get("Cf-Mitigated"), "challenge")
298	}
299	
300	func isSuccessfulFallback(response *http.Response, err error) bool {
301		return err == nil && response != nil &&
302			response.StatusCode >= http.StatusOK &&
303			response.StatusCode < http.StatusBadRequest
304	}
305	
306	func cloneRequestForRetry(request *http.Request) (*http.Request, bool) {
307		if !isIdempotent(request) {
308			return nil, false
309		}
310		retry := request.Clone(request.Context())
311		if request.Body == nil || request.Body == http.NoBody {
312			return retry, true
313		}
314		if request.GetBody == nil {
315			return nil, false
316		}
317		body, err := request.GetBody()
318		if err != nil {
319			return nil, false
320		}
321		retry.Body = body
322		return retry, true
323	}
324	
