1	// Package tempfiles tracks temporary paths owned by one downloader, without
2	// requiring a private parent directory or scanning the shared system temp root.
3	package tempfiles
4	
5	import (
6		"errors"
7		"io"
8		"os"
9		"sync"
10	)
11	
12	type Scope struct {
13		mu     sync.Mutex
14		paths  map[string]struct{}
15		closed bool
16	}
17	
18	// Track adopts a newly created unique path. Late creations are removed when
19	// shutdown has already begun. A nil scope leaves cleanup to the resource owner.
20	func (s *Scope) Track(path string) error {
21		if s == nil {
22			return nil
23		}
24		s.mu.Lock()
25		defer s.mu.Unlock()
26		if s.closed {
27			return errors.Join(io.ErrClosedPipe, os.RemoveAll(path))
28		}
29		if s.paths == nil {
30			s.paths = make(map[string]struct{})
31		}
32		s.paths[path] = struct{}{}
33		return nil
34	}
35	func (s *Scope) Remove(path string) error {
36		if s == nil {
37			return os.RemoveAll(path)
38		}
39		s.mu.Lock()
40		defer s.mu.Unlock()
41		if err := os.RemoveAll(path); err != nil {
42			return err
43		}
44		delete(s.paths, path)
45		return nil
46	}
47	func (s *Scope) Close() error {
48		if s == nil {
49			return nil
50		}
51		s.mu.Lock()
52		defer s.mu.Unlock()
53		s.closed = true
54		var result error
55		for path := range s.paths {
56			if err := os.RemoveAll(path); err != nil {
57				result = errors.Join(result, err)
58			} else {
59				delete(s.paths, path)
60			}
61		}
62		return result
63	}
