203	type adaptiveTransport struct {
204		native   http.RoundTripper
205		browsers map[Browser]http.RoundTripper
206		jar      http.CookieJar
207		session  *ImpersonationSession
208	}
209	
210	func (t *adaptiveTransport) RoundTrip(request *http.Request) (*http.Response, error) {
211		cacheKey := requestCacheKey(request.URL)
212		if t.session != nil {
213			if selected, ok := t.session.load(cacheKey); ok {
214				if selected.fallbackDisabled {
215					return t.native.RoundTrip(request)
216				}
217				return t.browsers[selected.browser].RoundTrip(request)
218			}
219		}
220	
221		response, err := t.native.RoundTrip(request)
222		if !shouldFallback(response, err) {
223			return response, err
224		}
225	
226		retry, ok := cloneRequestForRetry(request)
227		if !ok {
228			return response, err
229		}
230		if response != nil {
231			applyResponseCookies(t.jar, request, retry, response)
232			_ = response.Body.Close()
233		}
234	
235		browser := browserFromUserAgent(request.UserAgent())
236		response, err = t.browsers[browser].RoundTrip(retry)
237		if t.session != nil {
238			if isSuccessfulFallback(response, err) {
239				t.session.store(cacheKey, browser)
240			} else if err == nil && response != nil {
241				t.session.disableFallback(cacheKey)
242			}
243		}
244		return response, err
245	}
246	
247	func requestCacheKey(requestURL *url.URL) string {
248		cacheURL := *requestURL
249		cacheURL.Fragment = ""
250		cacheURL.RawFragment = ""
251		return cacheURL.String()
252	}
253	
254	func applyResponseCookies(jar http.CookieJar, request, retry *http.Request, response *http.Response) {
255		if jar == nil {
256			return
257		}
258		jar.SetCookies(request.URL, response.Cookies())
259		jarCookies := jar.Cookies(request.URL)
260		jarCookieNames := make(map[string]struct{}, len(jarCookies))
261		for _, cookie := range jarCookies {
262			jarCookieNames[cookie.Name] = struct{}{}
263		}
264		existingCookies := retry.Cookies()
265		retry.Header.Del("Cookie")
266		for _, cookie := range existingCookies {
267			if _, replaced := jarCookieNames[cookie.Name]; !replaced {
268				retry.AddCookie(cookie)
269			}
270		}
271		for _, cookie := range jarCookies {
272			retry.AddCookie(cookie)
273		}
274	}
275	
276	func (t *adaptiveTransport) CloseIdleConnections() {
277		closeIdleConnections(t.native)
278		for _, transport := range t.browsers {
279			closeIdleConnections(transport)
280		}
281	}
282	
283	func closeIdleConnections(transport http.RoundTripper) {
284		if closer, ok := transport.(interface{ CloseIdleConnections() }); ok {
285			closer.CloseIdleConnections()
286		}
287	}
288	
289	func shouldFallback(response *http.Response, err error) bool {
290		if err != nil {
291			return true
292		}
293		if response == nil {
294			return false
295		}
296		return response.StatusCode == http.StatusForbidden ||
297			strings.EqualFold(response.Header.Get("Cf-Mitigated"), "challenge")
298	}
299	
300	func isSuccessfulFallback(response *http.Response, err error) bool {
301		return err == nil && response != nil &&
302			response.StatusCode >= http.StatusOK &&
303			response.StatusCode < http.StatusBadRequest
304	}
305	
306	func cloneRequestForRetry(request *http.Request) (*http.Request, bool) {
307		if !isIdempotent(request) {
308			return nil, false
309		}
310		retry := request.Clone(request.Context())
311		if request.Body == nil || request.Body == http.NoBody {
312			return retry, true
313		}
314		if request.GetBody == nil {
315			return nil, false
316		}
317		body, err := request.GetBody()
318		if err != nil {
319			return nil, false
320		}
321		retry.Body = body
322		return retry, true
323	}
324	
325	func isIdempotent(request *http.Request) bool {
326		switch request.Method {
327		case http.MethodGet, http.MethodHead, http.MethodOptions, http.MethodTrace:
328			return true
329		}
330		return request.Header.Get("Idempotency-Key") != "" ||
331			request.Header.Get("X-Idempotency-Key") != ""
332	}
333	
334	func browserFromUserAgent(userAgent string) Browser {
335		userAgent = strings.ToLower(userAgent)
336		switch {
337		case strings.Contains(userAgent, "firefox"):
338			return BrowserFirefox
339		case strings.Contains(userAgent, "safari") &&
340			!strings.Contains(userAgent, "chrome") &&
341			!strings.Contains(userAgent, "chromium"):
342			return BrowserSafari
343		default:
344			return BrowserChrome
345		}
346	}
